def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")
    result = []
    stack = []
    temp = ""
    for char in paren_string:
        if char == "(":
            stack.append(char)
            temp += char
        elif char == ")":
            if stack:
                stack.pop()
                temp += char
                if not stack:
                    result.append(temp)
                    temp = ""
    return result

