import math

def poly(xs: list, x: float):
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])

def find_zero(xs: list):
    def derivative(xs):
        return [i * coeff for i, coeff in enumerate(xs)]

    def newton_raphson(x0, xs):
        for _ in range(100):
            x = x0 - poly(xs, x0) / poly(derivative(xs), x0)
            if abs(poly(xs, x)) < 1e-6:
                return x
            x0 = x
        return x0

    if len(xs) % 2 != 0:
        raise ValueError("Polynomial must have an even number of coefficients")

    x0 = -xs[1] / xs[0]
    return newton_raphson(x0, xs)


