from heapq import heappop, heappush

def minPath(grid, k):
    m, n = len(grid), len(grid[0])
    visited = set()
    pq = [(0, 0, 0, [])]
    while pq:
        val, x, y, path = heappop(pq)
        if len(path) == k:
            return path
        if (x, y) in visited:
            continue
        visited.add((x, y)
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n:
                heappush(pq, (val + grid[nx][ny], nx, ny, path + [grid[nx][ny]]))
    return []


