    strongest = extensions[0]
    for extension in extensions[1:]:
        CAP = sum(1 for c in extension if c.isupper())
        SM = sum(1 for c in extension if c.islower())
        strongest_CAP = sum(1 for c in strongest if c.isupper())
        strongest_SM = sum(1 for c in strongest if c.islower())
        if (CAP - SM) > (strongest_CAP - strongest_SM):
